<script setup>
import { onMounted, ref } from "vue"; import { useRoute } from "vue-router"; import { getAdminUser, resetAdminPassword } from "../../services/adminRepository"; const route=useRoute(),user=ref(null),loading=ref(true),error=ref(""),password=ref(""),toast=ref(""); async function load(){try{user.value=await getAdminUser(route.params.userId)}catch(e){error.value=e.response?.data?.detail||e.message||"加载失败"}finally{loading.value=false}} async function reset(){if(password.value.length<8){toast.value="密码至少 8 位";return}try{await resetAdminPassword(route.params.userId,password.value);toast.value="密码已重置，旧会话已失效";password.value=""}catch(e){toast.value=e.response?.data?.detail||"重置失败"}} onMounted(load);
</script>
<template><main class="portal-page admin-portal page-enter"><div class="portal-heading"><div><span class="portal-kicker">账号详情</span><h1>{{user?.display_name||user?.username||'用户'}}</h1><p>查看后端支持的资料字段与账号状态。</p></div></div><div v-if="loading" class="portal-loading"><i></i></div><div v-else-if="error" class="portal-error">{{error}}</div><section v-else class="admin-overview-grid"><article class="portal-panel"><h2>基本资料</h2><dl class="admin-status-detail"><div><dt>用户名</dt><dd>{{user.username}}</dd></div><div><dt>角色</dt><dd>{{user.role}}</dd></div><div><dt>学号 / 工号</dt><dd>{{user.student_number||user.teacher_number||'—'}}</dd></div><div><dt>学院 / 专业</dt><dd>{{user.college||'—'}} / {{user.major||'—'}}</dd></div><div><dt>状态</dt><dd>{{user.is_active?'正常':'已停用'}}</dd></div><div><dt>创建时间</dt><dd>{{user.created_at}}</dd></div></dl></article><article class="portal-panel"><h2>安全操作</h2><label>新密码<input v-model="password" type="password" minlength="8" autocomplete="new-password" /></label><button class="primary-button" @click="reset">重置密码</button><p class="muted">重置后后端会撤销该账号的 refresh token。</p></article></section></main></template>
